// Create the file
cat > index.js << 'EOF'
import chalk from 'chalk';

console.log(chalk.green('Catch logged successfully'));
console.log(chalk.yellow('Species not recognized — check spelling'));
console.log(chalk.red('Upload failed: network error'));
EOF

# Run it
node index.js

// In package.json, update the scripts section to:
// "scripts": {
//   "start": "node index.js",
//   "greet": "node -e \"console.log('Ready to log catches.')\""
// }

# After saving package.json:
npm run start
npm run greet
npm run          # lists available scripts
